from fastapi.responses import HTMLResponse


def updates_page():
    return HTMLResponse(r'''<!doctype html><html lang="en" class="nct-shell-loading"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>NCT · Updates and Recovery</title><style id="nct-shell-bootstrap">html.nct-shell-loading body{visibility:hidden}</style>
<style>:root{--bg:#09131c;--panel:#112330;--line:#304955;--text:#e8f2f6;--muted:#abc0cb;--blue:#74c7ff}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:15px/1.55 system-ui}header{padding:20px 4vw}main{max-width:1100px;margin:auto;padding:32px 24px}.panel{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:24px;margin:20px 0}h1{font-size:28px}h2{font-size:20px}p,li{color:var(--muted)}button{background:var(--panel);color:var(--text);border:1px solid var(--blue);border-radius:7px;padding:12px 18px;cursor:pointer}button:disabled{opacity:.6;cursor:wait}[hidden]{display:none!important}progress{width:100%}</style><script src="/assets/nct-session.js"></script></head><body><header>NCT · Network Correlation &amp; Triage</header><main><h1>Updates and Recovery</h1>
<section class="panel" data-guide-context="nct-updates"><h2>Open the recovery workspace</h2><p>Use the independent recovery workspace to upload an offline NCT update, review its checks, install it, or restore the saved pre-update version. It stays available while NCT restarts.</p><ol><li>Open the workspace while signed in. NCT starts it and verifies that it is ready.</li><li>Upload the single NCT update <code>.tar.gz</code> file and review the exact release and source-build checks. Validation does not replace NCT.</li><li>Choose Apply after current scan and collection work has finished. The helper checks the stopped data, independently verifies a cold backup, and then replaces NCT.</li><li>Verify an existing NCT account in the workspace. Return to NCT after the build, health, sign-in and retained-evidence checks pass.</li></ol><p>If an update fails, the workspace keeps the result and offers Restore saved backup. Restore returns to the backup time and preserves evidence collected after the backup separately.</p><button id="openRecovery" type="button">Open update and recovery workspace</button><progress id="launchProgress" hidden aria-label="Starting recovery workspace"></progress><p id="updateStatus" role="status" aria-live="polite"></p></section>
<section class="panel"><h2>Deployment support</h2><p>The trusted recovery helper must be installed once on the NCT host. The application does not receive Docker control. If NCT cannot start, use the host recovery launcher to open the same workspace with a short-lived access code.</p><p>This first adapter supports one Docker or Docker Compose NCT container with a dedicated bind-mounted evidence directory. Kubernetes updates remain unavailable until the separate controller and storage acceptance checks are completed.</p></section></main><script>
document.getElementById('openRecovery').onclick=async()=>{const button=document.getElementById('openRecovery'),status=document.getElementById('updateStatus'),progress=document.getElementById('launchProgress');button.disabled=true;progress.hidden=false;status.textContent='Starting the independent recovery workspace and checking readiness…';try{const response=await fetch('/api/updates/launch',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'}),value=await response.json();if(!response.ok)throw Error(value.detail||'Recovery workspace did not start');const palette={};for(const key of ['--bg','--panel','--line','--text','--muted','--blue'])palette[key]=getComputedStyle(document.documentElement).getPropertyValue(key).trim();location.assign(value.url+'&palette='+encodeURIComponent(JSON.stringify(palette)))}catch(error){status.textContent=error.message;button.disabled=false;progress.hidden=true}};
</script></body></html>''')


def console_page():
    return HTMLResponse(r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>NCT Recovery Console</title><style>
:root{color-scheme:dark;--bg:#09131c;--panel:#112330;--line:#304955;--text:#e8f2f6;--muted:#abc0cb;--blue:#74c7ff}*{box-sizing:border-box}[hidden]{display:none!important}body{margin:0;background:var(--bg);color:var(--text);font:15px/1.55 system-ui}header{border-bottom:1px solid var(--line);padding:20px max(24px,5vw)}main{max-width:1120px;margin:auto;padding:24px}h1{font-size:26px}h2{font-size:19px}p,small{color:var(--muted)}section,details{background:var(--panel);border:1px solid var(--line);padding:20px;border-radius:10px;margin:18px 0}summary{cursor:pointer}button,input{font:inherit;color:var(--text);background:var(--panel);border:1px solid var(--line);border-radius:6px;padding:9px 12px}button{cursor:pointer}button:disabled{opacity:.5;cursor:default}button.primary{border-color:var(--blue)}label{display:block;margin:12px 0}input{max-width:100%;display:block}progress{width:100%;accent-color:var(--blue)}.actions{display:flex;gap:10px;flex-wrap:wrap}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse}th,td{text-align:left;vertical-align:top;padding:10px;border-bottom:1px solid var(--line);overflow-wrap:anywhere}th{width:30%}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:14px/1.5 system-ui}.warning{border-left:4px solid #d7ab47}a{color:var(--blue)}:focus-visible{outline:2px solid var(--blue);outline-offset:3px}</style></head><body><header><strong>NCT</strong> · Independent Recovery Console</header><main><h1>Updates and Recovery</h1><p>This workspace remains available while NCT stops or restarts. All actions are recorded with the operator. Closing the browser does not cancel an update.</p><p id="status" role="status" aria-live="polite">Connecting to recovery helper…</p><progress id="busy" hidden aria-label="Recovery operation running"></progress>
<section id="access" hidden><h2>Host recovery access</h2><p>Enter the one-use access code printed by the host recovery launcher. It expires after two minutes. A stopped application does not bypass sign-in.</p><form id="accessForm"><label>Recovery access code<input id="code" type="password" autocomplete="off" required></label><button>Open recovery workspace</button></form></section>
<div id="workspace" hidden><section><h2>1. Upload and validate</h2><p>Choose a trusted NCT update <code>.tar.gz</code> package. Its image checksum is included. Validation checks the exact installed build, image identity, saved data compatibility and space. It loads the release image locally but does not replace or stop NCT. Original terminal deployment ZIP packages use the terminal installer.</p><form id="uploadForm"><label>Offline update package<input id="package" type="file" accept=".gz,.tgz" required></label><button id="upload" class="primary">Upload and validate package</button></form><p id="uploadStatus" role="status"></p></section>
<section><h2>2. Review and apply</h2><div class="table-wrap" data-nct-table-mode="static"><table><thead><tr><th>Check</th><th>Result</th></tr></thead><tbody id="checks"></tbody></table></div><p id="detail"></p><button id="apply" class="primary" disabled>Apply validated update</button><p>Apply stops NCT, checks unfinished work, verifies schema compatibility again, makes and independently restores a cold backup, then replaces NCT. Unresolved work blocks the update.</p></section>
<section id="verifySection" hidden><h2>3. Verify sign-in and finish</h2><p>Use an existing NCT account. The password is sent only to your local NCT instance for this check and is never saved by the recovery helper.</p><form id="verifyForm"><label>NCT username<input id="username" autocomplete="username" required></label><label>NCT password<input id="password" type="password" autocomplete="current-password" required></label><button>Verify sign-in</button></form></section>
<section id="repairSection" hidden><h2>Review unfinished-work repair</h2><p>NCT is stopped for this review. The check preserves completed evidence and valid waiting scans. Apply only after reviewing the affected work and blockers. Restored collection remains paused for review in NCT.</p><pre id="repairSummary"></pre><div class="actions"><button id="applyRepair" disabled>Apply reviewed work repair</button><button id="cancelRepair">Resume NCT without repair</button></div></section>
<details><summary>Recovery controls and diagnostics</summary><p>Start, stop and restart affect only the configured NCT container. Restore returns to the pre-update backup time; candidate evidence remains preserved separately. Review the diagnostic before making a change.</p><div class="actions"><button data-action="diagnose">Investigate NCT</button><button data-action="verify-backup">Verify saved backup</button><button id="prepareRepair">Check unfinished work for repair</button><button data-action="start">Start NCT</button><button data-action="stop">Stop NCT</button><button data-action="restart">Restart NCT</button><button id="rollback">Restore saved backup</button><button id="export">Export diagnostic summary</button></div><pre id="diagnostic" role="status"></pre></details>
<details open><summary>Operator Guide</summary><p>How to use this: follow Upload → Review → Apply → Verify. Keep this page open to see saved progress. If the browser disconnects, reopen the workspace from NCT or the host recovery launcher; the helper retains the operation.</p><p>How NCT uses this: the verified backup protects the existing accounts and evidence before the new release writes to them. A saved receipt connects the operator, package, original installation and verification results. Rollback restores that backup and keeps the failed or later data separately for investigation.</p><p>After a host interruption, the helper pauses for an explicit restore. It never guesses that an incomplete update succeeded. If restore cannot prove the original backup and container identity, it leaves the old application stopped and explains the failure.</p></details><button id="return">Return to NCT and close recovery workspace</button></div></main><script>
const $=id=>document.getElementById(id);let current={},applicationUrl='',working=false;
const fragment=new URLSearchParams(location.hash.slice(1)),handoff=fragment.get('handoff');history.replaceState(null,'',location.pathname);try{const serialized=fragment.get('palette')||sessionStorage.getItem('nct-recovery-palette')||'{}',palette=JSON.parse(serialized);for(const key of ['--bg','--panel','--line','--text','--muted','--blue'])if(typeof palette[key]==='string'&&palette[key].length<100&&CSS.supports('color',palette[key]))document.documentElement.style.setProperty(key,palette[key]);sessionStorage.setItem('nct-recovery-palette',serialized)}catch(_){}
async function api(route,body,method='POST'){const response=await fetch('/api'+route,{method,headers:{'Content-Type':'application/json','X-NCT-Recovery':'1'},...(method==='GET'?{}:{body:JSON.stringify(body||{})})});const value=await response.json();if(!response.ok)throw Error(value.detail||'Recovery action failed');return value}
function message(text){$('status').textContent=text}async function action(work){if(working)return;working=true;$('busy').hidden=false;try{await work()}catch(error){message(error.message)}finally{working=false;$('busy').hidden=true}}
function render(state){current=state.operation;applicationUrl=state.application_url;$('workspace').hidden=false;$('access').hidden=true;const rows=[['Operator',state.actor],['Update phase',({idle:'Ready',validated:'Ready to apply',fence_intent:'Stopping NCT',backup_verified:'Backup verified',replace_intent:'Replacing NCT',candidate_created:'Starting the new version',awaiting_sign_in:'Verify your NCT sign-in',awaiting_restore_sign_in:'Verify the restored NCT sign-in',awaiting_repair_sign_in:'Verify NCT after repair',repair_review:'Review unfinished work',repair_intent:'Repairing unfinished work',repair_verified:'Repair verified',release_intent:'Finishing verification',complete:'Update complete',restored:({work_repair:'Unfinished-work repair complete',preview_cancel:'Preview closed without repair',backup_restore:'Saved backup restored'})[current.completion_kind]||'Recovery complete',interrupted:'Needs recovery review',restore_intent:'Restoring the backup',restore_swap_intent:'Returning to the backup time'})[current.phase]||'Working'],['Release build',current.build_id||'No package validated'],['Commit',current.build_commit||'—'],['Last verified running build',current.running_build_id||'Not yet verified'],['Running build commit',current.running_build_commit||'Not yet verified'],['Cold backup',current.backup_verified?'Verified · '+new Date(current.backup_at*1000).toLocaleString():'Not yet created'],['Preserved post-backup data',current.quarantine_path||'No restore performed'],['Saved backup file',current.backup_path||'Not yet created'],['Retained evidence',current.evidence_verified?'Verified':'Not yet checked'],['Existing-account sign-in',current.controller_sign_in_verified?'Verified':'Not yet checked']];$('checks').replaceChildren();for(const [key,value] of rows){const row=document.createElement('tr');for(const text of [key,value]){const cell=document.createElement('td');cell.textContent=text;row.append(cell)}$('checks').append(row)}$('detail').textContent=current.detail||'Upload a package to begin.';$('apply').disabled=current.phase!=='validated';$('verifySection').hidden=!['awaiting_sign_in','awaiting_restore_sign_in','awaiting_repair_sign_in'].includes(current.phase);$('busy').hidden=!working&&['idle','validated','complete','restored','failed','interrupted','awaiting_sign_in','awaiting_restore_sign_in','awaiting_repair_sign_in'].includes(current.phase);message(current.detail||'Recovery workspace ready.')}
async function refresh(){try{render(await api('/status',null,'GET'));const canUpload=['idle','validated','complete','restored','failed'].includes(current.phase);$('upload').disabled=!canUpload;$('package').disabled=!canUpload;$('repairSection').hidden=current.phase!=='repair_review';if(current.repair_summary){const summary=current.repair_summary,lines=[`Work records needing repair: ${summary.affected_count}`,`Valid waiting scans preserved: ${summary.preserved_scan_queue}`,`Can apply: ${summary.safe_to_apply?'Yes':'Blocked'}`,...(summary.blockers||[])];for(const group of summary.categories||[]){lines.push('',group.category.replaceAll('_',' ')+':');for(const item of group.actions)lines.push('  '+item.record+' · '+item.action.replaceAll('_',' '))}$('repairSummary').textContent=lines.join('\n');$('applyRepair').disabled=!summary.safe_to_apply||!summary.affected_count}if(current.phase==='repair_review'){$('busy').hidden=true;message('Review the unfinished-work plan. NCT remains stopped.')}}catch(error){$('workspace').hidden=true;$('access').hidden=false;message(error.message)}}
async function exchange(code){await api('/exchange',{code});$('code').value='';await refresh()}
$('accessForm').onsubmit=event=>{event.preventDefault();action(()=>exchange($('code').value))};
$('uploadForm').onsubmit=event=>{event.preventDefault();action(async()=>{const file=$('package').files[0];if(!file)throw Error('Choose an NCT update package');$('uploadStatus').textContent='Uploading and validating. NCT continues running.';await new Promise((resolve,reject)=>{const request=new XMLHttpRequest();request.open('POST','/api/upload');request.setRequestHeader('X-NCT-Recovery','1');request.upload.onprogress=event=>{if(event.lengthComputable)$('uploadStatus').textContent='Upload '+Math.round(event.loaded/event.total*100)+'% · validation follows'};request.onload=()=>{try{const value=JSON.parse(request.responseText);if(request.status>=400)throw Error(value.detail);resolve(value)}catch(error){reject(error)}};request.onerror=()=>reject(Error('Upload interrupted. Reopen recovery workspace to inspect status.'));request.send(file)});$('uploadStatus').textContent='Validation completed.';await refresh()})};
$('apply').onclick=()=>action(async()=>{if(!confirm('Stop NCT, verify its cold backup, and install '+current.build_id+'?'))return;await api('/apply',{plan_digest:current.plan_digest});await refresh()});
$('rollback').onclick=()=>action(async()=>{if(!confirm('Restore the original pre-update backup? This returns NCT to the backup time. Evidence collected after the backup will be preserved separately.'))return;await api('/rollback',{confirm:'RESTORE'});await refresh()});
$('prepareRepair').onclick=()=>action(async()=>{if(!confirm('Stop NCT and make a verified cold backup to review unfinished work? NCT stays stopped until you apply the repair or resume without changes.'))return;await api('/prepare-repair');await refresh()});
$('applyRepair').onclick=()=>action(async()=>{if(!confirm('Apply this exact unfinished-work repair? Completed evidence and valid waiting scans are preserved. Collection remains paused for review.'))return;await api('/apply-repair',{plan_digest:current.plan_digest});await refresh()});
$('cancelRepair').onclick=()=>action(async()=>{if(!confirm('Resume NCT without repair? Its existing queues and automation may start again.'))return;await api('/cancel-repair',{confirm:'RESUME'});await refresh()});
$('verifyForm').onsubmit=event=>{event.preventDefault();action(async()=>{const password=$('password').value;$('password').value='';const verified=await api('/verify-sign-in',{username:$('username').value,password});await api('/close');location.assign(verified.url)})};
document.querySelectorAll('[data-action]').forEach(button=>button.onclick=()=>action(async()=>{const name=button.dataset.action;if(['stop','restart'].includes(name)&&!confirm(name+' the configured NCT instance?'))return;$('diagnostic').textContent=JSON.stringify(await api('/'+name,{},name==='diagnose'?'GET':'POST'),null,2);await refresh()}));
$('export').onclick=()=>action(async()=>{const value=await api('/diagnose',null,'GET'),url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download='nct-recovery-summary.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});
$('return').onclick=()=>action(async()=>{const value=await api('/close');location.assign(value.url)});
if(handoff)action(()=>exchange(handoff));else refresh();setInterval(()=>{if(!working&&!$('workspace').hidden)refresh()},3000);
</script></body></html>''')
